197	/// 坐标换算器:配置坐标 <-> 当前屏幕像素。
198	///
199	/// 这是**唯一**做坐标换算的地方:注入、绘制、取点、界面显示都走它。
200	/// 旧配置(像素)在升级前 `legacy` 为真,此时直通(与升级前行为完全一致)。
201	///
202	/// 注意:构造它需要读取配置,调用方若已持有配置锁,必须先取好 Mapper 再加锁,
203	/// 否则会自锁(同一把锁在同线程二次 lock)。
204	#[derive(Debug, Clone, Copy)]
205	pub struct Mapper {
206	    pub w: f32,
207	    pub h: f32,
208	    legacy: bool,
209	}
