211	impl Mapper {
212	    /// `space` 为当前屏幕(触摸坐标空间)尺寸
213	    pub fn new(unit: CoordUnit, space: (u32, u32)) -> Self {
214	        Self {
215	            w: space.0.max(1) as f32,
216	            h: space.1.max(1) as f32,
217	            legacy: unit == CoordUnit::Pixel,
218	        }
219	    }
220	
221	    /// 横坐标:配置值 -> 像素
222	    pub fn x(&self, v: f32) -> i32 {
223	        self.axis(v, self.w)
224	    }
225	
226	    /// 纵坐标:配置值 -> 像素
227	    pub fn y(&self, v: f32) -> i32 {
228	        self.axis(v, self.h)
229	    }
230	
231	    fn axis(&self, v: f32, size: f32) -> i32 {
232	        if self.legacy {
233	            v.round() as i32
234	        } else {
235	            (v * size).round() as i32
236	        }
237	    }
238	
239	    /// 点:配置值 -> 像素
240	    pub fn point(&self, x: f32, y: f32) -> (i32, i32) {
241	        (self.x(x), self.y(y))
242	    }
243	
244	    /// 长度(半径等,按屏幕宽度换算):配置值 -> 像素
245	    pub fn len(&self, v: f32) -> f32 {
246	        if self.legacy { v } else { v * self.w }
247	    }
248	
249	    /// 像素坐标 -> 配置值(取点时用)
250	    pub fn rel_x(&self, px: i32) -> f32 {
251	        if self.legacy {
252	            px as f32
253	        } else {
254	            px as f32 / self.w
255	        }
256	    }
257	
258	    pub fn rel_y(&self, px: i32) -> f32 {
259	        if self.legacy {
260	            px as f32
261	        } else {
262	            px as f32 / self.h
263	        }
264	    }
265	
266	    /// 像素长度 -> 配置值
267	    pub fn rel_len(&self, px: f32) -> f32 {
268	        if self.legacy { px } else { px / self.w }
269	    }
270	}
