458	/// 把滚轮增量累加成"齿数"(纯函数;W1-5)。
459	///
460	/// 物理滚轮(尤其高精度/带刻度的)常把一齿拆成多个小 `delta`,而钩子路径
461	/// 之前只取符号 —— 多齿的一次物理滚动会被压成 1 齿。这里按 `WHEEL_DELTA`
462	/// 累加:不足一齿的余量留在 `acc` 里等下一枚事件凑;超过一齿的按齿数发出
463	/// (除法朝零取整,正负对称)。超过上限的齿照常从 `acc` 里扣掉(不攒爆),
464	/// 但只发出上限次数 —— 与 Linux 侧"丢掉多余"的口径一致。
465	#[cfg(any(windows, test))]
466	pub(crate) fn wheel_notches(acc: &mut i32, delta: i32) -> i32 {
467	    *acc += delta;
468	    let n = *acc / WHEEL_DELTA;
469	    *acc -= n * WHEEL_DELTA;
470	    n.clamp(-WHEEL_NOTCH_CAP, WHEEL_NOTCH_CAP)
471	}
