/// 探针自愈停用后的兜底重装判定(纯函数;2026-10-11,DF-10)。
///
/// 全部条件都满足才放行:
/// - `probe_off`:只有"探针自愈已停用"这一种状态才走兜底(探针还活着时由它管);
/// - ① `now - last_event_ms >= FALLBACK_QUIET_MS`:这么久没有任何钩子事件
///   (`mark` 没被调用过 —— 键盘、鼠标按键与滚轮都算);
/// - ② `key_down`:`GetAsyncKeyState` 说此刻**确实有键按着** —— 用户在手按
///   而我们收不到,这才是"钩子被摘了"而不是"用户就是没按";
/// - ③ 限流:距上次兜底重装 ≥ `FALLBACK_COOLDOWN_MS`,且累计 < `FALLBACK_MAX`。
#[cfg(any(windows, test))]
pub(crate) fn fallback_reinstall_due(
    probe_off: bool,
    now: u64,
    last_event_ms: u64,
    key_down: bool,
    last_fallback_ms: u64,
    fallback_count: u32,
) -> bool {
    if !probe_off || !key_down || fallback_count >= FALLBACK_MAX {
        return false;
    }
    if now.saturating_sub(last_event_ms) < FALLBACK_QUIET_MS {
        return false;
    }
    if last_fallback_ms != 0 && now.saturating_sub(last_fallback_ms) < FALLBACK_COOLDOWN_MS {
        return false;
    }
    true
}
```

